```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // The contract guarantees len(text) <= 100000, so the text is sent as-is.
        // The host channel stamps its own session identity on the confirmation.
        // This node passes that identity back and never makes one up.
        let confirmation: DeliveryConfirmation = response_channel::send(&reply.text);

        // Ensures: delivered == true and present(session_id). If the host did not
        // accept the message or gave no session, reporting success would be false.
        // Trapping means no output is produced, so no output breaks the contract.
        if !confirmation.delivered {
            panic!("response channel did not accept the reply");
        }
        if confirmation.session.is_empty() {
            panic!("response channel returned no session identity");
        }

        confirmation
    }
}

export!(Node);
